import{_ as t,o as r,c as l,a2 as p}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph User + Dev Monthly Meeting 2024-08-21","description":"","frontmatter":{"title":"Ceph User + Dev Monthly Meeting 2024-08-21","date":"2024-08-21T00:00:00.000Z","updated":"2024-08-22T00:00:00.000Z","tags":["Ceph","用户体验","功能改进","Crush Map","upmap"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_User_+_Dev_Monthly_Meeting_2024-08-21.md","filePath":"posts/2024/Ceph_User_+_Dev_Monthly_Meeting_2024-08-21.md","lastUpdated":1780459816000}'),o={name:"posts/2024/Ceph_User_+_Dev_Monthly_Meeting_2024-08-21.md"};function s(n,e,i,a,g,_){return r(),l("div",null,[...e[0]||(e[0]=[p('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>会议主题</strong>： Ceph 分布式存储用户开发者会议，重点讨论了用户体验和 Ceph 功能改进。</p><p><strong>参会人员</strong>： Laura、Zach、Joel、Alex 等社区成员。</p><p><strong>会议内容</strong>：</p><p><strong>1. 用户体验（Usability）</strong></p><ul><li><strong>议题</strong>： 如何改进 Ceph 的用户体验，特别是针对非技术用户。</li><li><strong>讨论</strong>： <ul><li><strong>Joel</strong>： 提出在 Crush Map 中添加网络交换机信息，以帮助管理员更好地了解集群结构，但担心这会导致数据迁移。</li><li><strong>Alex</strong>： 建议使用 PG Remapper 或 upmap remapped 工具来避免数据迁移，并建议创建一个跟踪器来记录问题。</li><li><strong>Zach</strong>： 提出“冰镐倡议”（Ice Pick Initiative），旨在改进 Ceph 命令的帮助输出，使其更易于理解和使用。</li><li><strong>Garv</strong>： 讨论了 Ceph 仪表板的用户体验改进，计划进行社区调查以获取反馈。</li></ul></li><li><strong>决定事项</strong>： <ul><li>Joel 将创建一个跟踪器，记录添加网络交换机信息的问题，并尝试使用 PG Remapper 或 upmap remapped 工具来解决。</li><li>Zach 将开始实施冰镐倡议，并创建一个跟踪器来跟踪所有需要改进的命令。</li><li>Garv 将进行社区调查，以获取对 Ceph 仪表板用户体验的反馈。</li></ul></li></ul><p><strong>2. Ceph 功能改进</strong></p><ul><li><strong>议题</strong>： 讨论 Ceph 功能的改进，特别是与用户体验相关的改进。</li><li><strong>讨论</strong>： <ul><li><strong>Joel</strong>： 提出使用 upmap 来避免在添加网络交换机信息时进行数据迁移。</li><li><strong>Alex</strong>： 讨论了 upmap 和 upmap balancer 的工作原理，并建议 Joel 尝试使用这些工具来解决他的问题。</li><li><strong>Zach</strong>： 讨论了 Ceph 命令的帮助输出，并提出了改进建议。</li><li><strong>Garv</strong>： 讨论了 Ceph 仪表板的用户体验改进，并计划进行社区调查以获取反馈。</li></ul></li><li><strong>决定事项</strong>： 无</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Joel 将创建一个跟踪器，记录添加网络交换机信息的问题，并尝试使用 PG Remapper 或 upmap remapped 工具来解决。</li><li>Zach 将开始实施冰镐倡议，并创建一个跟踪器来跟踪所有需要改进的命令。</li><li>Garv 将进行社区调查，以获取对 Ceph 仪表板用户体验的反馈。</li><li>社区成员将提供反馈，以帮助改进 Ceph 的用户体验。</li></ul><p><strong>关键词</strong>： usability、Crush Map、upmap、upmap balancer、Ice Pick Initiative、Ceph 仪表板、用户体验</p>',12)])])}const c=t(o,[["render",s]]);export{u as __pageData,c as default};
